import sys


def price(quantity):
    if quantity < 0:
        raise ValueError('quantity must be non-negative')
    return quantity * 10


if __name__ == '__main__':
    try:
        result = price(int(sys.argv[1]))
    except ValueError as error:
        sys.exit(str(error))
    print(result)

