import unittest
import subprocess
import sys
from pathlib import Path
from app import price
class Tests(unittest.TestCase):
    def test_positive(self): self.assertEqual(price(2),20)

    def test_zero(self):
        self.assertEqual(price(0), 0)

    def test_negative(self):
        with self.assertRaises(ValueError):
            price(-1)

    def test_cli(self):
        for quantity, expected in [('2', '20\n'), ('0', '0\n')]:
            with self.subTest(quantity=quantity):
                result = subprocess.run(
                    [sys.executable, str(Path(__file__).with_name('app.py')), quantity],
                    capture_output=True, text=True,
                )
                self.assertEqual(result.returncode, 0)
                self.assertEqual(result.stdout, expected)
                self.assertEqual(result.stderr, '')

    def test_cli_negative(self):
        result = subprocess.run(
            [sys.executable, str(Path(__file__).with_name('app.py')), '-1'],
            capture_output=True, text=True,
        )
        self.assertNotEqual(result.returncode, 0)
        self.assertEqual(result.stdout, '')
        self.assertIn('quantity must be non-negative', result.stderr)
